<?php require 'config/bootstrap.php'; require_login(); $id=(int)($_GET['id']??0); $c=own_contract($id); $pdo=db(); $err=[];
if($_SERVER['REQUEST_METHOD']==='POST'){ csrf_check();
 if(($_POST['do']??'')==='delete'){ $vs=$pdo->prepare('SELECT stored_name FROM contract_versions WHERE contract_id=?');$vs->execute([$id]);$files=$vs->fetchAll(PDO::FETCH_COLUMN);
  $pdo->beginTransaction(); try{ foreach(['contract_comparisons','chat_messages','review_checklist_items','review_notes','reminders','payments','obligations','obligation_suggestions','risk_findings','clauses','analysis_results','activity_logs','contract_versions'] as $t) $pdo->prepare("DELETE FROM $t WHERE contract_id=?")->execute([$id]);
   $pdo->prepare('DELETE FROM contracts WHERE id=? AND user_id=?')->execute([$id,uid()]); $pdo->commit(); foreach($files as $f) @unlink(storage_dir().basename($f)); log_act('contract_deleted',null,$c['title']); flash('Contract deleted.'); header('Location: contracts.php'); exit; }
  catch(Throwable $e){ $pdo->rollBack(); error_log($e->getMessage()); $err[]='Delete failed.'; } }
 else { $t=trim($_POST['title']??''); if($t==='')$err[]='Title is required.'; $ed=valid_date($_POST['effective_date']??''); $xd=valid_date($_POST['expiry_date']??'');
  if(($_POST['effective_date']??'')&&!$ed)$err[]='Invalid effective date.'; if(($_POST['expiry_date']??'')&&!$xd)$err[]='Invalid expiry date.'; if($ed&&$xd&&$xd<$ed)$err[]='Expiry is before effective date.';
  if(!$err){ $pdo->prepare('UPDATE contracts SET title=?,contract_type=?,parties=?,description=?,effective_date=?,expiry_date=?,renewal_terms=?,notice_period_days=? WHERE id=? AND user_id=?')->execute([$t,trim($_POST['contract_type']),trim($_POST['parties']),trim($_POST['description']),$ed,$xd,trim($_POST['renewal_terms']),($_POST['notice']??'')!==''?max(0,(int)$_POST['notice']):null,$id,uid()]); log_act('metadata_changed',$id,$t); flash('Contract updated.'); header("Location: contract.php?id=$id"); exit; } $c=array_merge($c,$_POST,['notice_period_days'=>$_POST['notice']??'']); } }
page_head('Edit contract'); ?><a href="contract.php?id=<?=$id?>">&larr; Back</a><h1 class="h3 my-3">Edit contract</h1><?php foreach($err as $x):?><div class="alert alert-danger"><?=e($x)?></div><?php endforeach;?>
<form method="post" class="cardx row g-3"><?=csrf_field()?><div class="col-md-8"><label class="form-label">Title *</label><input class="form-control" name="title" required value="<?=e($c['title'])?>"></div>
