<div class="col-12"><label class="form-label">Renewal terms</label><input class="form-control" name="renewal_terms" value="<?=e($c['renewal_terms'])?>"></div><div class="col-12"><label class="form-label">Description</label><textarea class="form-control" name="description" rows="2"><?=e($c['description'])?></textarea></div>
